def biGraph(n, e, arr):
    if n <= 2:
        return 1

    from collections import defaultdict

    graph = defaultdict(list)
    for i in range(0, len(arr), 2):
        u, v = arr[i], arr[i + 1]
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    low = [0] * n
    disc = [0] * n
    parent = [-1] * n
    articulation_points = set()

    def dfs(u):
        children = 0
        visited[u] = True
        disc[u] = time
        low[u] = time
        time = time + 1

        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                children += 1
                dfs(v)

                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    articulation_points.add(u)

                if parent[u] != -1 and low[v] >= disc[u]:
                    articulation_points.add(u)

            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    time = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)

    return 1 if len(articulation_points) == 0 else 0

